'use strict';
// v1.7.1 · Family recipe form fixes, dish photos and community recipes (owner report from the iPhone, v1.7.0).
//
// 1. Ingredients: the family form only had one free-text box whose parser refused every line in a unit the shopping
//    list cannot count (“Tỏi 3 tép”, “2 lát gừng”) — the save failed with “Kiểm tra lượng và đơn vị”, so on a phone it
//    looked like ingredients could not be entered — and there was no way to choose a catalogue ingredient. The form now
//    has one row per ingredient: name with catalogue suggestions (combobox), amount (decimal keypad) and a unit picker,
//    rows can be added, removed and moved. Rows are written back to the original `ingredients` box, so the existing
//    save code, voice dictation and older data keep working. Lines in a non-shopping unit are kept verbatim and flagged
//    “not counted”, never converted or guessed.
// 2. Photos: the form had no photo control at all. A dish photo can be taken or chosen (iOS converts HEIC to JPEG when a
//    photo is picked with accept="image/*"); it is decoded, downscaled to ≤1600 px and re-encoded as JPEG on the device
//    (which also drops EXIF), kept on this device and uploaded with the family's other photos when signed in.
// 3. Community recipes: share a family recipe (whole recipe or photo + name) for moderation, browse approved community
//    recipes in the library, copy one to the family (marked with its source), report, unshare. Studio flag
//    `communityRecipes` (cached platform flags) hides everything when off.
const RC_API='/.netlify/functions/community-recipes';
const RC_SHOP_UNITS={g:['g',1],kg:['g',1000],'lạng':['g',100],ml:['ml',1],l:['ml',1000],'quả':['quả',1],'cái':['cái',1],'bó':['bó',1],'gói':['gói',1],'miếng':['miếng',1]};
// v1.7.5: these units are counted as written when “Cộng vào đi chợ” is ticked (never converted to grams).
const RC_NOTE_UNITS=[['tép','clove'],['củ','bulb'],['nhánh','knob / sprig'],['lát','slice'],['khoanh','round slice'],['cây','stalk'],['nắm','handful'],['con','whole'],['đòn','roll (pork sausage)'],['muỗng canh','tablespoon'],['muỗng cà phê','teaspoon'],['chén','bowl / cup'],['hộp','box'],['lon','can'],['chai','bottle'],['vỉ','tray / card'],['khay','tray'],['túi','bag']];
const RC_UNIT_EN={g:'g',kg:'kg','lạng':'100 g',ml:'mL',l:'L','quả':'each','cái':'piece','bó':'bunch','gói':'pack','miếng':'piece / cut'};
const rcT=(vi,en)=>typeof tr==='function'?tr(vi,en):vi;
const rcEsc=v=>typeof esc==='function'?esc(v):String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]);
const rcNorm=s=>typeof normalizeText==='function'?normalizeText(String(s||'')):String(s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/đ/g,'d').toLowerCase();
function rcEnabled(){try{return JSON.parse(localStorage.getItem('bep-platform-flags')||'{}')?.communityRecipes!==false}catch{return true}}

// ---------------------------------------------------------------- ingredient rows
let rcRowSeq=0;
function rcUnitOptions(sel){const shop=Object.keys(RC_SHOP_UNITS).map(u=>`<option value="${rcEsc(u)}" ${u===sel?'selected':''}>${rcEsc(rcT(u==='lạng'?'lạng (100 g)':u,RC_UNIT_EN[u]))}</option>`).join(''),note=RC_NOTE_UNITS.map(([u,en])=>`<option value="${rcEsc(u)}" ${u===sel?'selected':''}>${rcEsc(rcT(u,en))}</option>`).join(''),fam=rcFamilyUnits(),famHtml=fam.length?`<optgroup label="${rcEsc(rcT('Đơn vị của nhà mình (ghi theo chữ, không cộng)','Your family’s units (kept as written, not added up)'))}">${fam.map(u=>`<option value="${rcEsc(u)}" ${u===sel?'selected':''}>${rcEsc(u)}</option>`).join('')}</optgroup>`:'',custom=sel&&!RC_SHOP_UNITS[sel]&&!RC_NOTE_UNITS.some(x=>x[0]===sel)&&!fam.includes(sel)?`<option value="${rcEsc(sel)}" selected>${rcEsc(sel)}</option>`:'';return `<option value="" ${sel?'':'selected'}>${rcT('— đơn vị','— unit')}</option>${shop}${note}${famHtml}${custom}`}
// v1.7.18: units the family made in the buying sheet are offered here too. They are not shopping or note units, so a line
// written with one is saved as typed and never counted or converted (the same as a unit typed by hand).
function rcFamilyUnits():string[]{try{if(typeof state==='undefined'||typeof familyCustomUnits!=='function')return[];return familyCustomUnits(state).filter((u:any)=>!u.hidden&&!RC_SHOP_UNITS[u.name]&&!RC_NOTE_UNITS.some(x=>x[0]===u.name)).map((u:any)=>u.name).slice(0,60)}catch{return[]}}
// v1.7.19 (rule 29): the unit of a row is chosen in the same picker as the buying unit on Đi chợ (suggestions for the
// matched ingredient, “Xem tất cả đơn vị”, “Tự thêm đơn vị”, the family's own units). The row keeps the exact text chosen
// on a button whose value the save reads, so saved recipes and units the lists do not know stay as written.
const RC_NOTE_TITLE=()=>rcT('Đơn vị hay ghi trong công thức','Units written in recipes');
function rcUnitLabel(u){const v=String(u??'');if(!v)return '';if(RC_SHOP_UNITS[v])return rcT(v==='lạng'?'lạng (100 g)':v,RC_UNIT_EN[v]);const note=RC_NOTE_UNITS.find(x=>x[0]===v);if(note)return rcT(v,note[1]);return typeof unitFieldLabel==='function'?unitFieldLabel(v):v}
function rcUnitControl(n,sel){if(typeof openUnitSheet!=='function')return `<label class="rc-sr sr-only" for="rc-ing-unit-${n}">${rcT('Đơn vị','Unit')}</label><select id="rc-ing-unit-${n}" class="rc-ing-unit">${rcUnitOptions(sel)}</select>`;
 return `<button type="button" id="rc-ing-unit-${n}" class="rc-ing-unit unit-field-btn${sel?'':' is-empty'}" data-rci="unit" value="${rcEsc(sel)}" aria-haspopup="dialog" aria-label="${rcEsc(rcT('Đơn vị','Unit')+': '+(sel?rcUnitLabel(sel):rcT('chưa chọn','not chosen')))}">${rcEsc(sel?rcUnitLabel(sel):rcT('Chọn đơn vị','Pick a unit'))}</button>`}
function rcUnitButtonSync(li){const b=li?.querySelector('button.rc-ing-unit');if(!b)return;const v=b.value,t=v?rcUnitLabel(v):rcT('Chọn đơn vị','Pick a unit');if(b.textContent!==t)b.textContent=t;b.classList.toggle('is-empty',!v);b.setAttribute('aria-label',rcT('Đơn vị','Unit')+': '+(v?rcUnitLabel(v):rcT('chưa chọn','not chosen')))}
function rcOpenUnit(li,btn){const v=rcRowValue(li),ing=li.dataset.ing&&typeof INGREDIENTS!=='undefined'&&INGREDIENTS[li.dataset.ing]?li.dataset.ing:(typeof unitMatchIngredient==='function'?unitMatchIngredient(v.name):null);
 openUnitSheet({value:btn.value,ingredient:ing,name:v.name,title:rcT('Đơn vị trong công thức','Unit in the recipe'),defaults:['g','kg','ml','quả','bó','tép','muỗng canh','muỗng cà phê'],ownUnits:RC_NOTE_UNITS.map(x=>x[0]),ownTitle:RC_NOTE_TITLE(),labels:Object.fromEntries(RC_NOTE_UNITS.map(([u,en])=>[u,rcT(u,en)])),
  note:rcT('Đơn vị được ghi đúng như bạn chọn. g, kg, lạng, ml, l, quả, cái, bó, gói, miếng và các đơn vị trong công thức được cộng vào đi chợ; đơn vị khác giữ nguyên chữ.','The unit is kept exactly as chosen. g, kg, 100 g, ml, l, each, piece, bunch, pack, cut and the recipe units are added to shopping; other units are kept as written.'),
  returnEl:btn,onChoose:u=>{if(!btn.isConnected)return;btn.value=u;li.dataset.dirty='1';rcRowNote(li);rcSyncRows(btn.closest('form'))}})}
function rcRowMarkup(row={}){const n=++rcRowSeq;return `<li class="rc-ing-row" data-row="${n}"${row.orig?` data-orig="${rcEsc(row.orig)}"`:''}><div class="rc-ing-name"><label class="rc-sr sr-only" for="rc-ing-name-${n}">${rcT('Tên nguyên liệu','Ingredient name')}</label><input id="rc-ing-name-${n}" class="rc-ing-name-input" type="text" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="rc-sug-${n}" autocomplete="off" autocapitalize="sentences" enterkeyhint="next" maxlength="100" placeholder="${rcEsc(rcT('Tên (vd: thịt gà)','Name (e.g. chicken)'))}" value="${rcEsc(row.name||'')}"><div class="rc-sug" id="rc-sug-${n}" role="listbox" aria-label="${rcEsc(rcT('Gợi ý nguyên liệu','Ingredient suggestions'))}" hidden></div></div><label class="rc-sr sr-only" for="rc-ing-qty-${n}">${rcT('Lượng','Amount')}</label><input id="rc-ing-qty-${n}" class="rc-ing-qty" type="text" inputmode="decimal" enterkeyhint="next" maxlength="12" autocomplete="off" placeholder="${rcEsc(rcT('Lượng','Amount'))}" value="${rcEsc(row.qty??'')}">${rcUnitControl(n,row.unit||'')}<label class="rc-ing-shop"><input type="checkbox" class="rc-ing-shop-input" ${row.note?'':'checked'}><span>${rcT('Cộng vào đi chợ','Add to shopping list')}</span></label><div class="rc-ing-tools"><button type="button" class="rc-icon" data-rci="up" aria-label="${rcEsc(rcT('Chuyển lên','Move up'))}">↑</button><button type="button" class="rc-icon" data-rci="down" aria-label="${rcEsc(rcT('Chuyển xuống','Move down'))}">↓</button><button type="button" class="rc-icon rc-remove" data-rci="remove" aria-label="${rcEsc(rcT('Xoá dòng','Remove row'))}">×</button></div><p class="rc-ing-note" hidden></p></li>`}
/** One saved line → {name,qty,unit}. Accepts "tên | lượng | đơn vị" and natural "Thịt gà 500g" / "Tỏi 3 tép". */
// v1.7.16 (owner, 8 Nov 2026, a recipe page writing “Xương ống bò: 0.5kg”, “Bò tái:1,2kg”): “name: amount” is read too, with or
// without a space after the colon; the colon never stays in the name.
function rcParseLine(line){const t=String(line||'').trim();if(!t)return null;if(t.includes('|')){const [name,q,u,g]=t.split('|').map(x=>x.trim());return{name:(name||'').replace(/\s*[:：]+\s*$/,''),qty:q||'',unit:u||'',orig:t,note:g==='note'}}const m=t.match(/^(.*?[^\d\s\/.,¼½¾⅓⅔:：])(?:\s*[:：]\s*|\s+)(\d+\s+\d+\/\d+|\d*[¼½¾⅓⅔]|\d+(?:[.,]\d+)?(?:\/\d+)?)\s*([^\d|\/¼½¾⅓⅔]*)$/u);if(m){return{name:m[1].trim(),qty:m[2],unit:m[3].trim(),orig:t}}return{name:t.replace(/\s*[:：]+\s*$/,''),qty:'',unit:'',orig:t}}
function rcRowValue(li){return{name:li.querySelector('.rc-ing-name-input').value.trim(),qtyText:li.querySelector('.rc-ing-qty').value.trim(),unit:li.querySelector('.rc-ing-unit').value,shop:li.querySelector('.rc-ing-shop-input')?.checked!==false}}
const rcQty=t=>typeof parseQty==='function'?parseQty(t):Number(String(t).replace(',','.'));
const rcCountable=u=>!!RC_SHOP_UNITS[u]||RC_NOTE_UNITS.some(x=>x[0]===u);
/** Row → saved line for the original parser. Shopping units are converted exactly (kg→g, l→ml, lạng→100 g); anything
 *  else is written as the family typed it, so the save keeps it verbatim as "not counted". Nothing is invented. */
/* v1.7.5: a saved structured line is reused only while unchanged; free text (pasted “Chanh 1/2 quả”) is always written
   from what the row shows, so the save never re-reads it differently (it read 1/2 as 2 and dropped “đòn”). */
function rcRowLine(v,li){if(li?.dataset.orig&&li.dataset.orig.includes('|')&&!li.dataset.dirty&&rcRowUnchanged(v,li.dataset.orig))return li.dataset.orig;if(!v.name)return '';if(!v.shop)return `${v.name} | ${v.qtyText} | ${v.unit} | note`;const qty=rcQty(v.qtyText);if(v.qtyText&&Number.isFinite(qty)&&qty>0&&qty<1e6&&RC_SHOP_UNITS[v.unit]){const [base,f]=RC_SHOP_UNITS[v.unit];return `${v.name} | ${+(qty*f).toFixed(3)} | ${base}`}if(v.qtyText&&Number.isFinite(qty)&&qty>0&&qty<1e6&&rcCountable(v.unit))return `${v.name} | ${+qty.toFixed(3)} | ${v.unit}`;if(!v.qtyText)return v.name;return `${v.name} ${v.qtyText}${v.unit?' '+v.unit:''}`.trim()}
/** v1.7.3: the saved line is reused only while the row still shows exactly what it was opened with. iOS can change a
 *  field without an `input` event (keyboard dictation, QuickType/AutoFill, picker wheels), and then the old line —
 *  often just a name — replaced the amount and unit the family had entered. */
function rcRowUnchanged(v,orig){const p=rcParseLine(orig);return !!p&&p.name===v.name&&String(p.qty??'').trim()===v.qtyText&&String(p.unit||'')===String(v.unit||'')&&!p.note===v.shop}
function rcRowNote(li){rcUnitButtonSync(li);const v=rcRowValue(li),note=li.querySelector('.rc-ing-note'),qty=rcQty(v.qtyText);let msg='';if(!v.name)msg='';else if(!v.shop)msg=rcT('Chỉ ghi trong công thức, không cộng vào danh sách đi chợ.','Shown in the recipe only, not added to the shopping list.');else if(!v.qtyText)msg=rcT('Thêm lượng để cộng vào danh sách đi chợ.','Add an amount to put it on the shopping list.');else if(!Number.isFinite(qty)||qty<=0)msg=rcT('Lượng chưa đọc được (vd: 2, 0,5, 1/2) — giữ nguyên chữ, chưa cộng vào đi chợ.','Amount not understood (e.g. 2, 0.5, 1/2) — kept as written, not added to shopping.');else if(!v.unit)msg=rcT('Chọn đơn vị để cộng vào danh sách đi chợ.','Pick a unit to add it to the shopping list.');else if(!rcCountable(v.unit))msg=rcT(`Đơn vị “${v.unit}” giữ nguyên chữ, chưa cộng vào đi chợ.`,`“${v.unit}” is kept as written, not added to shopping.`);note.textContent=msg;note.hidden=!msg}
function rcSyncRows(form){const list=form?.querySelector('#rc-ing-list'),box=form?.querySelector('textarea[name="ingredients"]');if(!list||!box)return;box.value=[...list.querySelectorAll('.rc-ing-row')].map(li=>rcRowLine(rcRowValue(li),li)).filter(Boolean).join('\n');form.dataset.rcSynced=box.value}
function rcBuildRows(form,{focusLast=false}={}){const list=form.querySelector('#rc-ing-list'),box=form.querySelector('textarea[name="ingredients"]');if(!list||!box)return;const rows=box.value.split('\n').map(rcParseLine).filter(Boolean);list.innerHTML=(rows.length?rows:[{},{},{}]).map(rcRowMarkup).join('');list.querySelectorAll('.rc-ing-row').forEach(rcRowNote);form.dataset.rcSynced=box.value;if(typeof applyLanguage==='function')try{applyLanguage(list)}catch{}if(focusLast)list.querySelector('.rc-ing-row:last-child .rc-ing-name-input')?.focus()}
function rcIngredientEditorMarkup(){return `<fieldset class="field rc-ings" aria-describedby="rc-ings-help"><legend>${rcT('Nguyên liệu & định lượng','Ingredients & quantities')}</legend><div class="rc-ing-head" aria-hidden="true"><span>${rcT('Tên','Name')}</span><span>${rcT('Lượng','Amount')}</span><span>${rcT('Đơn vị','Unit')}</span></div><ol class="rc-ing-list" id="rc-ing-list"></ol><div class="toolbar rc-ing-actions"><button type="button" class="btn small" data-rci="add">+ ${rcT('Thêm nguyên liệu','Add ingredient')}</button></div><details class="rc-paste"><summary>${rcT('Dán danh sách nguyên liệu','Paste an ingredient list')}</summary><p class="hint">${rcT('Dán hoặc gõ mỗi dòng một nguyên liệu, rồi bấm “Thêm vào danh sách”. Ví dụ: “Thịt ba chỉ 500g”, “Tỏi 3 tép”, “Chả lụa 1 đòn”.','Paste or type one ingredient per line, then tap “Add to list”. For example: “Pork belly 500g”, “Garlic 3 cloves”.')}</p><label class="rc-sr sr-only" for="rc-paste-text">${rcT('Mỗi dòng một nguyên liệu','One ingredient per line')}</label><textarea id="rc-paste-text" rows="4" placeholder="${rcT('Thịt gà 500g&#10;Hành lá | 1 | bó','Chicken 500g&#10;Spring onions | 1 | bunch')}"></textarea><button type="button" class="btn small" data-rci="paste">${rcT('Thêm vào danh sách','Add to list')}</button></details><small class="hint" id="rc-ings-help">${rcT('Mỗi nguyên liệu có ô “Cộng vào đi chợ”. Bỏ chọn nếu nhà đã có sẵn (vd: muối, nước mắm). Lượng có thể ghi 2, 0,5 hoặc 1/2.','Each ingredient has an “Add to shopping list” tick. Untick it if you already have it (e.g. salt, fish sauce). Amounts can be 2, 0.5 or 1/2.')}</small></fieldset>`}

// ---------------------------------------------------------------- ingredient suggestions (combobox)
function rcSuggestions(q){const n=rcNorm(q).trim();if(n.length<1||typeof INGREDIENTS==='undefined')return[];const out=[];for(const [id,i] of Object.entries(INGREDIENTS)){const vi=rcNorm(i[0]),en=typeof INGREDIENT_EN!=='undefined'?rcNorm(INGREDIENT_EN[id]||''):'';let s=0;if(vi===n||en===n)s=100;else if(vi.startsWith(n)||en.startsWith(n))s=60;else if((' '+vi).includes(' '+n)||(' '+en).includes(' '+n))s=40;else if(vi.includes(n)||en.includes(n))s=10;if(s)out.push({id,name:i[0],unit:i[1],en:typeof INGREDIENT_EN!=='undefined'?INGREDIENT_EN[id]||'':'',s:s-Math.min(9,vi.length/10)})}return out.sort((a,b)=>b.s-a.s||a.name.localeCompare(b.name,'vi')).slice(0,6)}
function rcShowSug(input){const box=input.parentElement.querySelector('.rc-sug'),list=rcSuggestions(input.value);input.removeAttribute('aria-activedescendant');if(!list.length){box.hidden=true;box.innerHTML='';input.setAttribute('aria-expanded','false');return}box.innerHTML=list.map((x,k)=>`<button type="button" tabindex="-1" role="option" aria-selected="false" id="${box.id}-o${k}" class="rc-sug-opt" data-rci="pick" data-ing="${rcEsc(x.id)}" data-name="${rcEsc(x.name)}" data-unit="${rcEsc(x.unit)}"><span>${rcEsc(typeof appLanguage!=='undefined'&&appLanguage==='en'&&x.en&&rcNorm(x.en)!==rcNorm(x.name)?x.en+' · '+x.name:x.name)}</span><small>${rcEsc(rcT(x.unit,RC_UNIT_EN[x.unit]||x.unit))}</small></button>`).join('');box.hidden=false;input.setAttribute('aria-expanded','true')}
function rcHideSug(input){const box=input?.parentElement?.querySelector('.rc-sug');if(box){box.hidden=true;box.innerHTML=''}input?.setAttribute('aria-expanded','false');input?.removeAttribute('aria-activedescendant')}
function rcPick(opt){const li=opt.closest('.rc-ing-row'),input=li.querySelector('.rc-ing-name-input');input.value=opt.dataset.name;li.dataset.ing=opt.dataset.ing;li.dataset.dirty='1';/* v1.7.19 audit C2: the unit the family chose stays (1 con stayed 1 but became g); the catalogue unit fills an empty one only */const unit=li.querySelector('.rc-ing-unit');if(!unit.value)unit.value=opt.dataset.unit;rcHideSug(input);rcRowNote(li);rcSyncRows(li.closest('form'));li.querySelector('.rc-ing-qty').focus()}

// ---------------------------------------------------------------- photos (device → IndexedDB → family photo sync)
const rcPhotoURLs=new Map(),rcPhotoLoads=new Map();let rcFormPhoto=null,rcUploadBusy=false;
const rcIsHeic=f=>/image\/hei[cf]/i.test(f?.type||'')||/\.(heic|heif)$/i.test(f?.name||'');
/** Decode, downscale (≤1600 px) and re-encode as JPEG on the device. Throws a user-facing message. */
async function rcPreparePhoto(file,max=1600){if(!file)throw Error(rcT('Chưa chọn ảnh.','No photo chosen.'));if(file.size>30e6)throw Error(rcT('Ảnh quá lớn (tối đa 30 MB).','Photo too large (max 30 MB).'));if(file.type&&!/^image\//i.test(file.type)&&!rcIsHeic(file))throw Error(rcT('Tệp này không phải ảnh.','This file is not an image.'));
 let src=null,w=0,h=0,url='';const heicMsg=rcT('Không đọc được ảnh HEIC trên trình duyệt này. Trên iPhone hãy chọn ảnh từ Thư viện (máy tự đổi sang JPEG) hoặc vào Cài đặt › Camera › Định dạng › Tương thích nhất.','This browser cannot read HEIC photos. On iPhone pick the photo from the library (it is converted to JPEG) or set Settings › Camera › Formats › Most Compatible.');
 try{if(typeof createImageBitmap==='function'){src=await createImageBitmap(file,{imageOrientation:'from-image'});w=src.width;h=src.height}}catch{src=null}
 if(!src){try{url=URL.createObjectURL(file);const img=new Image();img.decoding='async';img.src=url;await img.decode();src=img;w=img.naturalWidth;h=img.naturalHeight}catch{if(url)URL.revokeObjectURL(url);throw Error(rcIsHeic(file)?heicMsg:rcT('Không đọc được ảnh. Dùng ảnh JPEG, PNG hoặc HEIC.','Could not read the photo. Use a JPEG, PNG or HEIC photo.'))}}
 try{if(!w||!h)throw Error('size');const scale=Math.min(1,max/Math.max(w,h)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(w*scale));c.height=Math.max(1,Math.round(h*scale));const g=c.getContext('2d');g.fillStyle='#fff';g.fillRect(0,0,c.width,c.height);g.drawImage(src,0,0,c.width,c.height);let blob=null;for(const q of [.84,.72,.6]){blob=await new Promise(r=>c.toBlob(r,'image/jpeg',q));if(blob&&blob.size<=900000)break}if(!blob)throw Error('encode');return{blob,width:c.width,height:c.height}}
 catch{throw Error(rcT('Không xử lý được ảnh này. Thử ảnh khác.','Could not process this photo. Try another one.'))}finally{if(url)URL.revokeObjectURL(url);try{src?.close?.()}catch{}}}
async function rcLocalPhoto(key,value){if(typeof localPhoto!=='function')return null;try{return await localPhoto(key,value)}catch{return null}}
async function rcPhotoURL(key){if(!key)return '';if(rcPhotoURLs.has(key))return rcPhotoURLs.get(key);if(rcPhotoLoads.has(key))return rcPhotoLoads.get(key);
 const p=(async()=>{let local=await rcLocalPhoto(key);if(!local?.blob&&typeof cloudConnection!=='undefined'&&cloudConnection.connected&&navigator.onLine&&typeof familyRequest==='function'){try{const res=await familyRequest('photo&id='+encodeURIComponent(key));if(res.ok){const blob=await res.blob();local={blob,uploaded:true};await rcLocalPhoto(key,local)}}catch{}}
  if(!local?.blob)return '';const u=URL.createObjectURL(local.blob);rcPhotoURLs.set(key,u);return u})();rcPhotoLoads.set(key,p);try{return await p}finally{rcPhotoLoads.delete(key)}}
function rcHydratePhotos(root=document){root.querySelectorAll?.('img[data-rc-photo]:not([data-rc-done])').forEach(img=>{img.dataset.rcDone='1';rcPhotoURL(img.dataset.rcPhoto).then(u=>{if(!u)return;img.src=u;img.hidden=false;img.closest('.rc-photo-wrap')?.classList.add('has-photo')})})}
async function rcUploadRecipePhotos(){if(rcUploadBusy||typeof cloudConnection==='undefined'||!cloudConnection.connected||typeof familyRequest!=='function')return;rcUploadBusy=true;try{for(const r of state.recipes||[]){const key=r.photo?.key;if(!key)continue;const local=await rcLocalPhoto(key);if(!local?.blob||local.uploaded)continue;const res=await familyRequest('photo&id='+encodeURIComponent(key),{method:'PUT',headers:{'Content-Type':'image/jpeg'},body:local.blob});if(res.status===423)return;if(!res.ok)throw Error('upload');await rcLocalPhoto(key,{...local,uploaded:true})}}catch{toast(rcT('Món ăn đã lưu; ảnh món còn trên máy và sẽ tải lên sau.','Recipe saved; the dish photo is kept on this device and will upload later.'),true)}finally{rcUploadBusy=false}}
if(typeof uploadPendingPhotos==='function'){const rcBaseUpload=uploadPendingPhotos;uploadPendingPhotos=async function(){try{await rcBaseUpload.apply(this,arguments)}finally{await rcUploadRecipePhotos()}}}
// Family recipe photos sit on top of the dish illustration (the illustration stays as fallback while loading/offline).
if(typeof foodArt==='function'){const rcBaseArt=foodArt;foodArt=function(r,hero){const art=rcBaseArt.apply(this,arguments);/* ladybug #28: a menu copy made before the photo was added still shows the family recipe's photo */if(!r?.photo?.key&&r?.id){const lib=(typeof state!=='undefined'?state.recipes:[])?.find((x:any)=>x.id===r.id&&x.photo?.key);if(lib)r={...r,photo:lib.photo}}if(!r?.photo?.key)return art;return `<span class="rc-photo-wrap">${art}<img class="rc-recipe-photo" data-rc-photo="${rcEsc(r.photo.key)}" alt="${rcEsc(rcT('Ảnh món ','Photo of ')+(r.name||''))}" hidden></span>`}}
function rcPhotoFieldMarkup(r){return `<div class="field rc-photo-field"><span class="rc-label" id="rc-photo-label">${rcT('Ảnh món (không bắt buộc)','Dish photo (optional)')}</span><div class="rc-photo-box" role="group" aria-labelledby="rc-photo-label"><div class="rc-photo-preview" id="rc-photo-preview">${r?.photo?.key?`<img data-rc-photo="${rcEsc(r.photo.key)}" alt="${rcEsc(rcT('Ảnh món hiện tại','Current dish photo'))}" hidden>`:''}<span class="rc-photo-empty" ${r?.photo?.key?'hidden':''}>🍲</span></div><div class="rc-photo-actions"><label class="btn small rc-file-btn">📷 ${rcT('Chụp ảnh','Take photo')}<input class="rc-file-input" type="file" accept="image/*" capture="environment" data-rc-file="camera"></label><label class="btn small rc-file-btn">🖼 ${r?.photo?.key?rcT('Đổi ảnh','Replace photo'):rcT('Chọn ảnh','Choose photo')}<input class="rc-file-input" type="file" accept="image/*" data-rc-file="library"></label><button type="button" class="btn small rc-photo-remove" data-rci="photo-remove" ${r?.photo?.key?'':'hidden'}>${rcT('Xoá ảnh','Remove photo')}</button></div></div><p class="hint rc-photo-status" id="rc-photo-status" role="status" aria-live="polite"></p></div>`}
function rcPhotoPreview(url){const box=$('#rc-photo-preview');if(!box)return;box.querySelectorAll('img').forEach(i=>i.remove());box.querySelector('.rc-photo-empty').hidden=!!url;if(url){const img=document.createElement('img');img.src=url;img.alt=rcT('Ảnh món mới','New dish photo');box.prepend(img)}const rm=$('.rc-photo-remove');if(rm)rm.hidden=!url}
async function rcOnFile(input){const file=input.files?.[0];input.value='';if(!file)return;const status=$('#rc-photo-status');if(status)status.textContent=rcT('Đang xử lý ảnh…','Processing photo…');try{const p=await rcPreparePhoto(file);if(rcFormPhoto?.url)URL.revokeObjectURL(rcFormPhoto.url);rcFormPhoto={state:'new',blob:p.blob,url:URL.createObjectURL(p.blob)};rcPhotoPreview(rcFormPhoto.url);if(status)status.textContent=rcT(`Ảnh đã sẵn sàng (${p.width}×${p.height}, ${Math.round(p.blob.size/1024)} KB). Bấm Lưu để giữ.`,`Photo ready (${p.width}×${p.height}, ${Math.round(p.blob.size/1024)} KB). Save to keep it.`)}catch(e){if(status)status.textContent=e.message;toast(e.message,true)}}

// ---------------------------------------------------------------- form enhancement
function rcEnhanceForm(id){const form=$('#family-recipe-form');if(!form||form.dataset.rcForm)return;form.dataset.rcForm='1';rcFormPhoto=null;const r=id?state.recipes.find(x=>x.id===id):null,own=r&&ownRecipe(r);
 const box=form.querySelector('textarea[name="ingredients"]'),field=box?.closest('.field');if(field){field.hidden=true;field.classList.add('rc-raw-ingredients');field.insertAdjacentHTML('afterend',rcIngredientEditorMarkup());rcBuildRows(form)}
 const name=form.querySelector('input[name="name"]')?.closest('.field');name?.insertAdjacentHTML('afterend',rcPhotoFieldMarkup(own?r:null));
 // Copying a library recipe keeps its illustration; the photo control starts empty. Voice dictation fills the original
 // box right after the form opens, so the rows are rebuilt once from it.
 queueMicrotask(()=>{if(form.isConnected&&box&&box.value!==form.dataset.rcSynced)rcBuildRows(form)});rcHydratePhotos(form)}
if(typeof familyRecipeEditor==='function'){const rcBaseEditor=familyRecipeEditor;familyRecipeEditor=function(id){const out=rcBaseEditor.apply(this,arguments);const enhance=()=>{try{rcEnhanceForm(id)}catch(e){console.error('recipe form',e)}};enhance();
 // v1.7.3: on a fresh start the editor first waits for the recipe library (offline-downloads wraps it and returns a
 // promise), so the form did not exist yet here and opened without the ingredient rows and photo field.
 if(out&&typeof out.then==='function')return out.then(v=>{enhance();return v});return out}}
// The family save handler is a capture listener on document that stops the event, so this runs on window (capture,
// earlier): write rows to the box first; afterwards attach/remove the photo.
window.addEventListener('submit',event=>{const form=event.target;if(form?.id!=='family-recipe-form'||!form.dataset.rcForm)return;rcSyncRows(form);const before=new Set((state.recipes||[]).map(r=>r.id)),editId=form.dataset.id,photo=rcFormPhoto;rcFormPhoto=null;
 setTimeout(async()=>{if(form.isConnected){rcFormPhoto=photo;return}if(!photo)return;const r=editId?state.recipes.find(x=>x.id===editId):state.recipes.find(x=>!before.has(x.id)&&ownRecipe(x));if(!r)return;
  if(photo.state==='removed'){delete r.photo;if(typeof refreshPlannedDishes==='function')refreshPlannedDishes(state,r);save(rcT('Đã xoá ảnh món.','Dish photo removed.'));render();return}
  const key='recipe-'+uid().replace(/[^a-zA-Z0-9-]/g,'').slice(0,60);try{await rcLocalPhoto(key,{blob:photo.blob,uploaded:false});rcPhotoURLs.set(key,photo.url);r.photo={key,updatedAt:new Date().toISOString()};/* v1.7.9 (ladybug #28: “đã đăng ảnh món rồi mà ngoài menu vẫn không hiển thị”): the photo is added after the save already refreshed the menu's copies, so refresh them again */if(typeof refreshPlannedDishes==='function')refreshPlannedDishes(state,r);save(rcT('Đã lưu món ăn kèm ảnh.','Recipe and photo saved.'));render();rcUploadRecipePhotos()}catch{toast(rcT('Đã lưu món ăn nhưng chưa lưu được ảnh trên máy.','Recipe saved, but the photo could not be stored on this device.'),true)}},0)},true);
document.addEventListener('change',event=>{const t=event.target;if(t?.matches?.('[data-rc-file]')){rcOnFile(t);return}if(t?.closest?.('#rc-ing-list')){const li=t.closest('.rc-ing-row');if(li){li.dataset.dirty='1';rcRowNote(li)}rcSyncRows(t.closest('form'))}});
document.addEventListener('input',event=>{const t=event.target;if(!t?.closest?.('#rc-ing-list'))return;if(t.classList.contains('rc-ing-name-input')){delete t.closest('.rc-ing-row').dataset.ing;if(!event.isComposing)rcShowSug(t)}const li=t.closest('.rc-ing-row');if(li){li.dataset.dirty='1';rcRowNote(li)}rcSyncRows(t.closest('form'))});
document.addEventListener('compositionend',event=>{const t=event.target;if(t?.classList?.contains('rc-ing-name-input'))rcShowSug(t)});
document.addEventListener('focusout',event=>{const t=event.target;if(t?.closest?.('#rc-ing-list .rc-ing-row'))rcSyncRows(t.closest('form'));if(t?.classList?.contains('rc-ing-name-input'))setTimeout(()=>{if(!t.parentElement?.contains(document.activeElement))rcHideSug(t)},180)});
// Keep focus in the name box while an option is tapped (touch and mouse), so the tap is not lost to blur.
document.addEventListener('pointerdown',event=>{if(event.target.closest?.('.rc-sug-opt'))event.preventDefault()});
document.addEventListener('keydown',event=>{const t=event.target;if(event.key==='Enter'&&!event.isComposing&&t?.closest?.('.rc-ing-row')&&t.matches('input')){const box=t.parentElement.querySelector('.rc-sug');if(!(box&&!box.hidden&&t.getAttribute('aria-activedescendant'))){event.preventDefault();const f=[...t.closest('#rc-ing-list').querySelectorAll('input,select,.rc-ing-unit')],i=f.indexOf(t);(f[i+1]||t.closest('.rc-ings').querySelector('[data-rci="add"]'))?.focus();if(t.classList.contains('rc-ing-name-input'))rcHideSug(t);return}}if(!t?.classList?.contains('rc-ing-name-input'))return;const box=t.parentElement.querySelector('.rc-sug'),opts=box&&!box.hidden?[...box.querySelectorAll('.rc-sug-opt')]:[];if(event.key==='Escape'&&opts.length){event.preventDefault();event.stopPropagation();rcHideSug(t);return}if(!opts.length||!['ArrowDown','ArrowUp','Enter'].includes(event.key))return;let i=opts.findIndex(o=>o.id===t.getAttribute('aria-activedescendant'));if(event.key==='Enter'){if(i<0)return;event.preventDefault();rcPick(opts[i]);return}event.preventDefault();i=event.key==='ArrowDown'?(i+1)%opts.length:(i<=0?opts.length-1:i-1);opts.forEach((o,k)=>o.setAttribute('aria-selected',String(k===i)));t.setAttribute('aria-activedescendant',opts[i].id);opts[i].scrollIntoView?.({block:'nearest'})},true);
document.addEventListener('click',event=>{const b=event.target.closest?.('[data-rci]');if(!b||!b.closest('#family-recipe-form'))return;event.preventDefault();const form=b.closest('form'),list=form.querySelector('#rc-ing-list'),li=b.closest('.rc-ing-row');
 switch(b.dataset.rci){
  case'add':list.insertAdjacentHTML('beforeend',rcRowMarkup());list.lastElementChild.querySelector('.rc-ing-name-input').focus();break;
  case'remove':{const next=li.nextElementSibling||li.previousElementSibling;li.remove();if(!list.children.length)list.insertAdjacentHTML('beforeend',rcRowMarkup());(next&&next.isConnected?next:list.lastElementChild).querySelector('.rc-ing-name-input').focus();break}
  case'up':if(li.previousElementSibling){li.previousElementSibling.before(li);b.focus()}break;
  case'down':if(li.nextElementSibling){li.nextElementSibling.after(li);b.focus()}break;
  case'pick':rcPick(b);break;
  case'unit':if(li&&typeof openUnitSheet==='function')rcOpenUnit(li,b);return;
  case'paste':{const ta=form.querySelector('#rc-paste-text'),rows=String(ta.value||'').split('\n').map(rcParseLine).filter(Boolean);if(!rows.length)break;[...list.querySelectorAll('.rc-ing-row')].filter(x=>!rcRowValue(x).name).forEach(x=>x.remove());list.insertAdjacentHTML('beforeend',rows.map(rcRowMarkup).join(''));list.querySelectorAll('.rc-ing-row').forEach(rcRowNote);ta.value='';b.closest('details').open=false;break}
  case'photo-remove':if(rcFormPhoto?.url)URL.revokeObjectURL(rcFormPhoto.url);rcFormPhoto={state:'removed'};rcPhotoPreview('');{const s=$('#rc-photo-status');if(s)s.textContent=rcT('Ảnh sẽ được xoá khi bấm Lưu.','The photo is removed when you save.')}break}
 rcSyncRows(form)});

// ---------------------------------------------------------------- community API helpers
let rcStatusCache=null,rcList={items:null,at:0,loading:false,error:''},rcMine={map:null,at:0};
async function rcFetch(op,options={}){const res=await fetch(RC_API+'?op='+op,{credentials:'same-origin',cache:'no-store',...options});let data={};try{data=await res.json()}catch{}if(!res.ok){const e=Error(typeof appLanguage!=='undefined'&&appLanguage==='en'?data.errorEn||data.error||'Request failed':data.error||data.errorEn||'Lỗi');e.status=res.status;e.data=data;throw e}return data}
async function rcStatus(force=false){if(!force&&rcStatusCache&&Date.now()-rcStatusCache.at<60000)return rcStatusCache.data;try{const d=await rcFetch('status');rcStatusCache={at:Date.now(),data:d};return d}catch{return{enabled:rcEnabled(),signedIn:false,offline:!navigator.onLine}}}
async function rcMyShares(force=false){if(!force&&rcMine.map&&Date.now()-rcMine.at<30000)return rcMine.map;try{const d=await rcFetch('mine');rcMine={map:new Map(d.shares.map(s=>[s.sourceId,s])),at:Date.now()}}catch{rcMine={map:new Map(),at:Date.now()}}return rcMine.map}
const rcStatusLabel=s=>({pending:rcT('Đang chờ duyệt','Pending review'),approved:rcT('Đã hiện trong Cộng đồng','Live in Community'),rejected:rcT('Không được duyệt','Not approved'),removed:rcT('Đã bị gỡ','Removed')})[s]||s;

// ---------------------------------------------------------------- share (recipe detail of a FAMILY recipe)
async function rcShareSection(r){const c=document.querySelector('#modal-root .modal-content');if(!c||c.querySelector('.rc-share-card')||!rcEnabled())return;const card=document.createElement('section');card.className='card rc-share-card';card.setAttribute('aria-labelledby','rc-share-title');card.innerHTML=`<h3 id="rc-share-title">🌏 ${rcT('Chia sẻ lên cộng đồng','Share to community')}</h3><p class="hint" data-rc-share-state>${rcT('Đang kiểm tra…','Checking…')}</p>`;c.appendChild(card);
 const st=await rcStatus();if(!card.isConnected)return;const p=card.querySelector('[data-rc-share-state]');
 if(st.enabled===false){card.remove();return}
 if(!st.signedIn){p.textContent=st.offline?rcT('Cần kết nối mạng để chia sẻ.','Sharing needs a connection.'):rcT('Đăng nhập tài khoản gia đình để chia sẻ món này với các gia đình khác. Món ăn vẫn dùng bình thường trên máy này.','Sign in to your family account to share this recipe with other families. It keeps working on this device either way.');return}
 if(st.viewer){p.textContent=rcT('Tài khoản chỉ xem không chia sẻ được.','View-only accounts cannot share.');return}
 const mine=(await rcMyShares(true)).get(r.id);if(!card.isConnected)return;
 if(mine){p.innerHTML=`<span class="pill rc-status rc-${rcEsc(mine.status)}">${rcEsc(rcStatusLabel(mine.status))}</span> ${rcEsc(mine.kind==='photo'?rcT('Chỉ ảnh + tên','Photo + name only'):rcT('Cả món','Whole recipe'))} · ${rcEsc(mine.by||rcT('Ẩn danh','Anonymous'))}${mine.reason?`<br>${rcT('Lý do','Reason')}: ${rcEsc(mine.reason)}`:''}${mine.points?`<br>+${mine.points} ${rcT('điểm cộng đồng','community points')}`:''}`;card.insertAdjacentHTML('beforeend',`<div class="toolbar"><button type="button" class="btn small" data-rc="share" data-id="${rcEsc(r.id)}">${rcT('Chia sẻ lại / cập nhật','Share again / update')}</button><button type="button" class="btn small danger" data-rc="unshare" data-id="${rcEsc(mine.id)}" data-source="${rcEsc(r.id)}">${rcT('Gỡ khỏi cộng đồng','Remove from community')}</button></div>`);return}
 p.textContent=rcT('Gửi món này (hoặc chỉ ảnh + tên món) để các gia đình khác tham khảo. Món ăn chỉ hiện sau khi được duyệt; món gốc của bạn không đổi.','Send this recipe (or only its photo + name) for other families. It appears only after review; your own recipe is unchanged.');card.insertAdjacentHTML('beforeend',`<div class="toolbar"><button type="button" class="btn primary small" data-rc="share" data-id="${rcEsc(r.id)}">${rcT('Chia sẻ lên cộng đồng','Share to community')}</button></div>`)}
if(typeof showRecipe==='function'){const rcBaseShow=showRecipe;showRecipe=function(id,snapshot,mealContext){const out=rcBaseShow.apply(this,arguments);try{const r=!snapshot&&state.recipes.find(x=>x.id===id);if(r&&ownRecipe(r))rcShareSection(r);rcHydratePhotos(document.querySelector('#modal-root')||document)}catch{}return out}}
function rcShareModal(r){const st=rcStatusCache?.data||{};const hasPhoto=!!r.photo?.key,fam=st.familyName||rcT('Gia đình của bạn','Your family');
 modal(rcT('Chia sẻ lên cộng đồng','Share to community'),`<form id="rc-share-form" data-id="${rcEsc(r.id)}"><p><b>${rcEsc(r.name)}</b></p><fieldset class="rc-choice"><legend>${rcT('Chia sẻ gì?','What to share?')}</legend><label class="checked-label"><input type="radio" name="kind" value="full" checked> ${rcT('Cả món: tên, nguyên liệu với định lượng của gia đình, cách nấu, ảnh','Whole recipe: name, ingredients with your quantities, method, photo')}</label><label class="checked-label"><input type="radio" name="kind" value="photo" ${hasPhoto?'':'disabled'}> ${rcT('Chỉ ảnh + tên món','Photo + dish name only')}${hasPhoto?'':` <small class="hint">(${rcT('món chưa có ảnh','no photo yet')})</small>`}</label></fieldset><fieldset class="rc-choice"><legend>${rcT('Hiện tên','Show as')}</legend><label class="checked-label"><input type="radio" name="display" value="family" checked> ${rcEsc(fam)}</label><label class="checked-label"><input type="radio" name="display" value="anonymous"> ${rcT('Ẩn danh','Anonymous')}</label></fieldset>${hasPhoto?`<label class="checked-label"><input type="checkbox" name="withPhoto" checked> ${rcT('Gửi kèm ảnh món','Include the dish photo')}</label>`:''}<label class="checked-label rc-consent"><input type="checkbox" name="consent" required> ${rcT('Tôi đồng ý chia sẻ món này công khai sau khi được duyệt, đây là món/ảnh của gia đình tôi, và có thể gỡ bất cứ lúc nào.','I agree to share this publicly after review; this is my family’s own recipe/photo, and I can remove it any time.')}</label><p class="hint">${rcT('Không gửi tên tài khoản, email hay dữ liệu gia đình khác. Ảnh được thu nhỏ và xoá thông tin ẩn (vị trí, máy chụp).','No account name, e-mail or other family data is sent. Photos are resized and hidden data (location, camera) removed.')} <a href="/privacy.html#community-recipes" target="_blank" rel="noopener">${rcT('Quyền riêng tư','Privacy')}</a></p><p class="hint" id="rc-share-status" role="status" aria-live="polite"></p></form>`,`<button class="btn" data-action="close-modal">${rcT('Huỷ','Cancel')}</button><button class="btn primary" data-rc="share-send" data-id="${rcEsc(r.id)}">${rcT('Gửi để duyệt','Send for review')}</button>`)}
function rcSharedIngredients(r){/* v1.7.20 (rule 29): the shared dish lists its lines in the family's own order, like Viết món and the dish sheet (recipeLineOrder) */const ing=r.ingredients||[],keys=typeof recipeLineOrder==='function'?recipeLineOrder(r).filter((k:string)=>k[0]==='i').map((k:string)=>+k.slice(1)):ing.map((_:any,k:number)=>k);const out=[];for(const k of keys){const i=ing[k];const x=i&&INGREDIENTS[i.id];if(x)out.push({name:x[0],qty:i.qty,unit:x[1]})}return out}
async function rcSendShare(id){const r=state.recipes.find(x=>x.id===id),form=$('#rc-share-form'),status=$('#rc-share-status');if(!r||!form)return;const d=new FormData(form);if(d.get('consent')!=='on'){if(status)status.textContent=rcT('Hãy tích ô đồng ý trước khi gửi.','Tick the consent box first.');form.querySelector('[name="consent"]')?.focus();return}
 const kind=d.get('kind')==='photo'?'photo':'full',withPhoto=!!r.photo?.key&&(kind==='photo'||d.get('withPhoto')==='on');const btn=$('[data-rc="share-send"]');if(btn)btn.disabled=true;if(status)status.textContent=rcT('Đang gửi…','Sending…');
 try{const body={consent:true,kind,display:d.get('display')==='anonymous'?'anonymous':'family',sourceId:r.id,recipe:{name:r.name,category:r.category,time:r.time,yield:typeof familyYield==='function'?familyYield(r):r.yield,ingredients:rcSharedIngredients(r),missing:r.missingIngredients||[],prep:r.prep||'',steps:r.steps||[]}};
  const res=await rcFetch('share',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
  if(withPhoto){const local=await rcLocalPhoto(r.photo.key);let blob=local?.blob;if(!blob){const u=await rcPhotoURL(r.photo.key);if(u)blob=await (await fetch(u)).blob()}if(blob)await rcFetch('share-photo&id='+encodeURIComponent(res.id),{method:'POST',headers:{'Content-Type':'image/jpeg'},body:blob});else if(kind==='photo')throw Error(rcT('Không tìm thấy ảnh trên máy này.','The photo is not on this device.'))}
  rcMine.at=0;closeModal();toast(rcT('Đã gửi. Món ăn sẽ hiện trong Cộng đồng sau khi được duyệt.','Sent. It appears in Community after review.'))}
 catch(e){if(status)status.textContent=e.message;if(btn)btn.disabled=false}}
async function rcUnshare(id,sourceId){const ok=typeof confirmDialog==='function'?await confirmDialog({title:rcT('Gỡ món ăn khỏi cộng đồng?','Remove from community?'),body:rcT('Bản chia sẻ và ảnh bị xoá khỏi kho cộng đồng. Món gốc của gia đình giữ nguyên.','The shared copy and photo are deleted from the community pool. Your family recipe stays as it is.'),confirmLabel:rcT('Gỡ','Remove'),danger:true}):true;if(!ok)return;try{await rcFetch('unshare',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});rcMine.at=0;rcList.at=0;toast(rcT('Đã gỡ khỏi cộng đồng.','Removed from community.'));if(sourceId&&$('#modal-root .rc-share-card'))showRecipe(sourceId)}catch(e){toast(e.message,true)}}

// ---------------------------------------------------------------- library: Community source
let rcActive=false,rcQuery='',rcCat='all';
async function rcLoadList(force=false){if(rcList.loading)return;if(!force&&rcList.items&&Date.now()-rcList.at<60000)return;rcList.loading=true;rcList.error='';rcRefresh();try{const d=await rcFetch('list');rcList.items=d.recipes||[];rcList.at=Date.now()}catch(e){rcList.error=e.status===404?'disabled':!navigator.onLine?rcT('Cần kết nối mạng để xem món ăn cộng đồng.','Community recipes need a connection.'):e.message}finally{rcList.loading=false;rcRefresh()}}
const rcPhotoSrc=x=>`${RC_API}?op=photo&id=${encodeURIComponent(x.id)}&v=${x.photoVersion||0}`;
function rcCopiedId(x){return state.recipes.find(r=>r.source?.type==='community'&&r.source.id===x.id)?.id||''}
function rcCard(x){const copied=rcCopiedId(x),more='rc-more-'+x.id,art=x.hasPhoto?`<img class="rc-community-photo" src="${rcEsc(rcPhotoSrc(x))}" alt="${rcEsc(x.name)}" loading="lazy">`:foodArt({category:x.category,protein:'mixed',name:x.name,id:'community-'+x.id});
 const body=x.kind==='full'?`<h4>${rcT('Nguyên liệu','Ingredients')}${x.yield?` · ${x.yield} ${rcT('suất','portions')}`:''}</h4><ul class="rc-ing-view">${(x.ingredients||[]).map(i=>`<li>${rcEsc(i.name)}${i.qty!=null?` — <b>${rcEsc(+i.qty)} ${rcEsc(i.unit||'')}</b>`:''}</li>`).join('')}${(x.missing||[]).map(m=>`<li>${rcEsc(m)} <small class="hint">(${rcT('chưa rõ lượng','amount not given')})</small></li>`).join('')}</ul>${x.prep?`<h4>${rcT('Chuẩn bị','Preparation')}</h4><p>${rcEsc(x.prep)}</p>`:''}${(x.steps||[]).length?`<h4>${rcT('Cách nấu','Method')}</h4><ol>${x.steps.map(s=>`<li>${rcEsc(s)}</li>`).join('')}</ol>`:''}`:`<p class="hint">${rcT('Gia đình này chỉ chia sẻ ảnh và tên món.','This family shared only the photo and dish name.')}</p>`;
 return `<article class="card recipe-card lib-card rc-card" data-rc-id="${rcEsc(x.id)}"><div class="recipe-visual lib-card-img rc-card-img">${art}</div><div class="recipe-info"><h3 class="lib-card-title">${rcEsc(x.name)}</h3><p class="rc-by">${x.by?rcEsc(x.by):rcT('Ẩn danh','Anonymous')} · <span class="pill soft">${x.kind==='full'?rcT('Công thức','Recipe'):rcT('Ảnh + tên','Photo + name')}</span>${typeof CATEGORY!=='undefined'&&CATEGORY[x.category]?` <span class="pill soft">${rcEsc(CATEGORY[x.category])}</span>`:''}</p><details class="rc-more" id="${rcEsc(more)}"><summary>${x.kind==='full'?rcT('Xem công thức','View recipe'):rcT('Chi tiết','Details')}</summary>${body}</details><div class="toolbar">${copied?`<button type="button" class="btn soft" data-action="recipe-detail" data-id="${rcEsc(copied)}">✓ ${rcT('Đã có trong món nhà','In your family recipes')}</button>`:`<button type="button" class="btn primary" data-rc="copy" data-id="${rcEsc(x.id)}">${rcT('Chép thành món nhà','Copy to my family')}</button>`}<button type="button" class="btn" data-rc="report" data-id="${rcEsc(x.id)}">${rcT('Báo cáo','Report')}</button></div></div></article>`}
function rcRows(){const q=rcNorm(rcQuery).trim();return (rcList.items||[]).filter(x=>(rcCat==='all'||x.category===rcCat)&&(!q||rcNorm(x.name+' '+(x.ingredients||[]).map(i=>i.name).join(' ')).includes(q)))}
function rcResults(){if(rcList.error==='disabled')return `<div class="card empty"><p>${rcT('Món ăn cộng đồng đang tắt.','Community recipes are turned off.')}</p></div>`;if(rcList.error&&!rcList.items)return `<div class="card empty"><p>${rcEsc(rcList.error)}</p><button type="button" class="btn" data-rc="reload">${rcT('Thử lại','Try again')}</button></div>`;if(!rcList.items)return `<p class="hint" role="status">${rcT('Đang tải món ăn cộng đồng…','Loading community recipes…')}</p>`;const rows=rcRows();if(!rcList.items.length)return `<div class="card empty"><h3>${rcT('Chưa có món ăn cộng đồng','No community recipes yet')}</h3><p>${rcT('Mở một món gia đình và bấm “Chia sẻ lên cộng đồng” để là gia đình đầu tiên.','Open a family recipe and tap “Share to community” to be the first.')}</p></div>`;if(!rows.length)return `<div class="card empty library-no-match"><h3>${rcT('Không tìm thấy món ăn phù hợp','No matching recipes')}</h3></div>`;return `<div class="recipe-grid lib-grid rc-grid">${rows.map(rcCard).join('')}</div>`}
function rcStatusText(){const n=rcList.items?rcRows().length:0;return rcList.items?rcT(`${n} món cộng đồng`,`${n} community recipes`)+(rcQuery.trim()?` · “${rcQuery.trim()}”`:''):''}
function rcView(){const chip=(k,l)=>`<button type="button" class="chip ${rcCat===k?'active':''}" data-rc="cat" data-id="${k}" aria-pressed="${rcCat===k}">${l}</button>`;return `<div class="filter-bar rc-filter"><input id="rc-search" class="input" type="search" enterkeyhint="search" autocomplete="off" autocapitalize="off" spellcheck="false" aria-controls="rc-results" aria-label="${rcEsc(rcT('Tìm món ăn cộng đồng','Search community recipes'))}" placeholder="${rcEsc(rcT('Tìm món ăn cộng đồng…','Search community recipes…'))}" value="${rcEsc(rcQuery)}"><div class="chip-row lib-cat-row" role="group" aria-label="${rcEsc(rcT('Lọc món ăn','Filter recipes'))}">${chip('all',rcT('Tất cả','All'))}${typeof CATEGORY!=='undefined'?Object.entries(CATEGORY).map(([k,v])=>chip(k,rcEsc(v))).join(''):''}</div></div><p class="hint" id="rc-community-note">${rcT('Món ăn do các gia đình khác chia sẻ và đã được duyệt. Định lượng giữ đúng như gia đình chia sẻ.','Shared by other families and reviewed. Quantities are exactly as the family shared them.')}</p><p id="rc-status" class="hint recipe-result-count" role="status" aria-live="polite">${rcStatusText()}</p><div id="rc-results">${rcResults()}</div>`}
function rcRefresh(){const box=$('#rc-results');if(!box||!rcActive)return;box.innerHTML=rcResults();const s=$('#rc-status');if(s)s.textContent=rcStatusText();if(typeof applyLanguage==='function')try{applyLanguage(box)}catch{}}
if(typeof renderRecipes==='function'){const rcBaseRender=renderRecipes;renderRecipes=function(){let html=rcBaseRender.apply(this,arguments);if(!rcEnabled()){rcActive=false;return html}const at=html.indexOf('<div class="filter-bar">'),end=html.lastIndexOf('</div>',at);if(at<0||end<0)return html;const tab=`<button type="button" data-rc="tab" role="tab" aria-selected="${rcActive}" class="${rcActive?'active':''}">${rcT('Cộng đồng','Community')}${rcList.items?` (${rcList.items.length})`:''}</button>`;let head=html.slice(0,end)+tab+html.slice(end,at);if(!rcActive)return head+html.slice(at);head=head.replace(/(data-fm="(?:all|own|samples)" role="tab") aria-selected="true" class="active"/,'$1 aria-selected="false" class=""');return head+rcView()}}
document.addEventListener('click',event=>{if(rcActive&&event.target.closest?.('[data-fm="all"],[data-fm="own"],[data-fm="samples"]'))rcActive=false},true);
document.addEventListener('input',event=>{if(event.target?.id!=='rc-search'||event.isComposing)return;rcQuery=event.target.value;rcRefresh()});
document.addEventListener('compositionend',event=>{if(event.target?.id==='rc-search'){rcQuery=event.target.value;rcRefresh()}});
function rcCopy(id){const x=(rcList.items||[]).find(y=>y.id===id);if(!x)return;const existing=rcCopiedId(x);if(existing){showRecipe(existing);return}
 const catalog=clone(state.ingredientCatalog||{}),ingredients=[],missing=[];
 for(const i of x.kind==='full'?x.ingredients||[]:[]){if(i.qty==null||!i.unit){missing.push(String(i.name).slice(0,290));continue}const u=RC_SHOP_UNITS[i.unit];if(!u){missing.push(`${i.name} ${+i.qty} ${i.unit}`.slice(0,290));continue}const qty=+(i.qty*u[1]).toFixed(3),unit=u[0];let ingId=Object.keys(INGREDIENTS).find(k=>rcNorm(INGREDIENTS[k][0])===rcNorm(i.name)&&INGREDIENTS[k][1]===unit)||Object.keys(catalog).find(k=>rcNorm(catalog[k].name)===rcNorm(i.name)&&catalog[k].unit===unit);if(!ingId){if(Object.keys(catalog).length>=500){missing.push(`${i.name} ${+i.qty} ${i.unit}`.slice(0,290));continue}ingId='family-ing-'+uid();catalog[ingId]={name:String(i.name).slice(0,100),unit,group:'dry'}}const f=ingredients.find(y=>y.id===ingId);if(f)f.qty+=qty;else ingredients.push({id:ingId,qty})}
 for(const m of x.missing||[])missing.push(String(m).slice(0,290));
 const cat=Object.hasOwn(CATEGORY,x.category)?x.category:'main',recipe={id:uid(),name:String(x.name).slice(0,150),category:cat,protein:'mixed',time:Number.isFinite(x.time)?x.time:30,servings:4,yield:Number.isFinite(x.yield)&&x.yield>0?x.yield:4,purposes:typeof defaultPurposesForCategory==='function'?defaultPurposesForCategory(cat):[],ingredients,missingIngredients:missing,prep:String(x.prep||''),steps:(x.steps||[]).map(String),custom:true,origin:'family',favorite:false,source:{type:'community',id:x.id,by:x.by||null,kind:x.kind,copiedAt:new Date().toISOString()}};
 const candidate={...state,ingredientCatalog:catalog};if(typeof hydrateFamilyIngredients==='function'&&!hydrateFamilyIngredients(candidate)){toast(rcT('Không chép được nguyên liệu.','Could not copy the ingredients.'),true);return}state.ingredientCatalog=catalog;state.recipes.push(recipe);save(rcT('Đã chép thành món nhà.','Copied to your family recipes.'));render();
 if(x.hasPhoto)fetch(rcPhotoSrc(x)).then(r=>r.ok?r.blob():null).then(async blob=>{if(!blob)return;const key='recipe-'+uid().replace(/[^a-zA-Z0-9-]/g,'').slice(0,60);await rcLocalPhoto(key,{blob,uploaded:false});const r=state.recipes.find(y=>y.id===recipe.id);if(!r)return;r.photo={key,updatedAt:new Date().toISOString()};save();render();rcUploadRecipePhotos()}).catch(()=>{})}
async function rcReport(id){const st=await rcStatus();if(!st.signedIn){toast(rcT('Đăng nhập tài khoản gia đình để báo cáo món ăn.','Sign in to your family account to report a recipe.'),true);return}const x=(rcList.items||[]).find(y=>y.id===id);const reasons=[['wrong',rcT('Sai / thiếu thông tin','Wrong or misleading')],['offensive',rcT('Nội dung không phù hợp','Inappropriate content')],['copyright',rcT('Ảnh / món của người khác','Someone else’s photo/recipe')],['spam',rcT('Quảng cáo / spam','Advertising / spam')],['other',rcT('Khác','Other')]];
 modal(rcT('Báo cáo món ăn','Report recipe'),`<form id="rc-report-form"><p><b>${rcEsc(x?.name||'')}</b></p><div class="field"><label for="rc-report-reason">${rcT('Lý do','Reason')}</label><select id="rc-report-reason" name="reason">${reasons.map(([k,l])=>`<option value="${k}">${rcEsc(l)}</option>`).join('')}</select></div><div class="field"><label for="rc-report-note">${rcT('Ghi chú (không bắt buộc)','Note (optional)')}</label><textarea id="rc-report-note" name="note" maxlength="300" rows="3"></textarea></div><p class="hint" id="rc-report-status" role="status" aria-live="polite"></p></form>`,`<button class="btn" data-action="close-modal">${rcT('Huỷ','Cancel')}</button><button class="btn primary" data-rc="report-send" data-id="${rcEsc(id)}">${rcT('Gửi báo cáo','Send report')}</button>`)}
async function rcSendReport(id){const f=$('#rc-report-form');if(!f)return;try{const r=await rcFetch('report',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,reason:f.reason.value,note:f.note.value})});closeModal();toast(r.duplicate?rcT('Bạn đã báo cáo món ăn này rồi.','You already reported this recipe.'):rcT('Đã gửi báo cáo. Cảm ơn bạn.','Report sent. Thank you.'))}catch(e){const s=$('#rc-report-status');if(s)s.textContent=e.message}}
document.addEventListener('click',event=>{const b=event.target.closest?.('[data-rc]');if(!b||b.tagName==='FORM')return;event.preventDefault();event.stopPropagation();const id=b.dataset.id;
 switch(b.dataset.rc){
  case'tab':rcActive=true;familyRecipePage=0;render();rcLoadList();{const t=$('[data-rc="tab"]');t?.focus();t?.scrollIntoView?.({block:'nearest',inline:'nearest'})}break;
  case'reload':rcLoadList(true);break;
  case'cat':rcCat=id||'all';$$('[data-rc="cat"]').forEach(c=>{const on=c.dataset.id===rcCat;c.classList.toggle('active',on);c.setAttribute('aria-pressed',String(on))});rcRefresh();break;
  case'copy':rcCopy(id);break;
  case'report':rcReport(id);break;
  case'report-send':rcSendReport(id);break;
  case'share':{const r=state.recipes.find(x=>x.id===id);if(r)rcStatus().then(()=>rcShareModal(r));break}
  case'share-send':rcSendShare(id);break;
  case'unshare':rcUnshare(id,b.dataset.source);break}});
// Photos inside newly rendered views/modals.
if(typeof MutationObserver!=='undefined'&&typeof document!=='undefined'){const rcObs=new MutationObserver(()=>{if(document.querySelector('img[data-rc-photo]:not([data-rc-done])'))rcHydratePhotos()});const start=()=>{rcObs.observe(document.body,{childList:true,subtree:true});rcHydratePhotos()};if(document.body)start();else document.addEventListener('DOMContentLoaded',start)}
